SELECT setval('daily_prices_id_seq',(SELECT MAX(id) FROM daily_prices));
SELECT setval('index_values_id_seq',(SELECT MAX(id) FROM index_values));
SELECT setval('reports_report_id_seq',(SELECT MAX(report_id) FROM reports));
SELECT setval('financials_financial_id_seq',(SELECT MAX(financial_id) FROM financials));
SELECT setval('valuation_ratios_valuation_id_seq',(SELECT MAX(valuation_id) FROM valuation_ratios));
COMMIT;